package net.farmingtales.ftboss.boss.ai;

import java.util.*;
import org.objectweb.asm.Opcodes;
import org.objectweb.asm.tree.*;

public final class NativeXueliPanStartInstaller implements Opcodes {
    private static final String ROOT="net/farmingtales/ftboss/",BOSS=ROOT+"entity/EasterBossEntity",LEVEL="net/minecraft/server/level/ServerLevel",LIVING="net/minecraft/world/entity/LivingEntity";
    private static final String DESC="(L"+LEVEL+";L"+LIVING+";)V",PREIMAGE="2611630062d9a8680f446c32bf5f31754ba560762068282044ab71b3c81551af";
    private NativeXueliPanStartInstaller(){}
    private static void require(boolean value,String reason){if(!value)throw new IllegalStateException(reason);}
    private static MethodNode method(ClassNode owner){require(owner.name.equals(BOSS),"Exact native Boss owner required");List<MethodNode> methods=owner.methods.stream().filter(value->value.name.equals("skillXueliPanSlap")&&value.desc.equals(DESC)).toList();require(methods.size()==1,"Exact single native pan start required");return methods.getFirst();}
    private static List<AbstractInsnNode> code(Iterable<AbstractInsnNode> instructions){List<AbstractInsnNode> result=new ArrayList<>();for(AbstractInsnNode instruction:instructions)if(instruction.getOpcode()>=0)result.add(instruction);return result;}
    private static MethodInsnNode one(MethodNode method,String owner,String name,String descriptor){List<MethodInsnNode> calls=new ArrayList<>();for(AbstractInsnNode instruction:method.instructions)if(instruction instanceof MethodInsnNode member&&member.owner.equals(owner)&&member.name.equals(name)&&member.desc.equals(descriptor))calls.add(member);require(calls.size()==1,"Exact pan start call inventory: "+owner+"."+name);return calls.getFirst();}
    private static AbstractInsnNode previous(AbstractInsnNode instruction){AbstractInsnNode result=instruction.getPrevious();while(result!=null&&result.getOpcode()<0)result=result.getPrevious();return result;}
    private static boolean equal(AbstractInsnNode left,AbstractInsnNode right){if(left==null||left.getOpcode()!=right.getOpcode())return false;if(left instanceof VarInsnNode value&&right instanceof VarInsnNode wanted)return value.var==wanted.var;if(left instanceof LdcInsnNode value&&right instanceof LdcInsnNode wanted)return Objects.equals(value.cst,wanted.cst);if(left instanceof FieldInsnNode value&&right instanceof FieldInsnNode wanted)return value.owner.equals(wanted.owner)&&value.name.equals(wanted.name)&&value.desc.equals(wanted.desc);if(left instanceof MethodInsnNode value&&right instanceof MethodInsnNode wanted)return value.owner.equals(wanted.owner)&&value.name.equals(wanted.name)&&value.desc.equals(wanted.desc)&&value.itf==wanted.itf;return left instanceof InsnNode&&right instanceof InsnNode;}
    private static InsnList nativeAction(){InsnList result=new InsnList();result.add(new VarInsnNode(ALOAD,0));result.add(new LdcInsnNode("pan_cast"));result.add(new LdcInsnNode("charge"));result.add(new VarInsnNode(ALOAD,0));result.add(new FieldInsnNode(GETFIELD,BOSS,"xueliPanWind","I"));result.add(new MethodInsnNode(INVOKESTATIC,ROOT+"xueli_cast_actions/CastServer","nativeAction","(L"+BOSS+";Ljava/lang/String;Ljava/lang/String;I)V",false));return result;}
    private static InsnList combatCharge(){InsnList result=new InsnList();result.add(new VarInsnNode(ALOAD,0));result.add(new InsnNode(ICONST_3));result.add(new MethodInsnNode(INVOKESTATIC,ROOT+"combat/xueli/XueliCombatServer","charge","(L"+BOSS+";I)V",false));return result;}
    private static void removeThrough(MethodNode method,AbstractInsnNode last,InsnList expected){List<AbstractInsnNode> wanted=code(expected);List<AbstractInsnNode> removed=new ArrayList<>();AbstractInsnNode cursor=last;for(int index=wanted.size()-1;index>=0;index--){require(equal(cursor,wanted.get(index)),"Exact original pan hook operands/ordering differ");removed.add(cursor);cursor=previous(cursor);}for(AbstractInsnNode instruction:removed)method.instructions.remove(instruction);}
    public static void install(ClassNode owner){MethodNode method=method(owner);if(!NativeBossLivingComposerSupportV2.methodFingerprint(method).equals(PREIMAGE)){verify(method);return;}MethodInsnNode cast=one(method,BOSS,"playCast","(II)V");require(cast.getOpcode()==INVOKEVIRTUAL,"Original virtual playCast anchor");method.instructions.insert(cast,nativeAction());List<AbstractInsnNode> returns=code(method.instructions).stream().filter(value->value.getOpcode()==RETURN).toList();require(returns.size()==1,"Exact native single terminal return");method.instructions.insertBefore(returns.getFirst(),combatCharge());method.maxStack=Math.max(method.maxStack,4);verify(method);}
    private static void verify(MethodNode source){MethodNode restored=NativeBossLivingComposerSupportV2.copy(source);removeThrough(restored,one(restored,ROOT+"xueli_cast_actions/CastServer","nativeAction","(L"+BOSS+";Ljava/lang/String;Ljava/lang/String;I)V"),nativeAction());removeThrough(restored,one(restored,ROOT+"combat/xueli/XueliCombatServer","charge","(L"+BOSS+";I)V"),combatCharge());require(NativeBossLivingComposerSupportV2.methodFingerprint(restored).equals(PREIMAGE),"Whole frozen native pan start changed outside exact two original callback additions");}
    public static void verifyInstalled(ClassNode owner){verify(method(owner));}
}
